"use client";

import type { ComponentProps } from "react";
import { motion, useReducedMotion } from "motion/react";

import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import styles from "./detailedbutton.module.css";

export type DetailedButtonVariant = "blue" | "graphite" | "violet" | "green";

const MotionButton = motion.create(Button);

type DetailedButtonProps = Omit<ComponentProps<typeof MotionButton>, "variant" | "asChild"> & {
  variant?: DetailedButtonVariant;
};

export default function DetailedButton({
  variant = "blue",
  className,
  type = "button",
  disabled,
  ...props
}: DetailedButtonProps) {
  const reduceMotion = useReducedMotion();
  const skipMotion = reduceMotion || disabled;

  return (
    <MotionButton
      {...props}
      type={type}
      disabled={disabled}
      whileHover={skipMotion ? undefined : { y: -2 }}
      whileTap={skipMotion ? undefined : { y: 1, scale: 0.98 }}
      transition={{ type: "spring", stiffness: 450, damping: 30 }}
      className={cn(styles.button, styles[variant], className)}
    />
  );
}

.blue {
  --button-fill: #296ff0;
}

.graphite {
  --button-fill: #34363c;
}

.violet {
  --button-fill: #7650df;
}

.green {
  --button-fill: #187b59;
}

.button.button {
  position: relative;
  height: 54px;
  gap: 12px;
  padding: 0 24px;
  border: 0;
  border-radius: 18px;
  background: var(--button-fill);
  color: #fff;
  font-size: 22px;
  font-weight: 400;
  letter-spacing: -0.5px;
  box-shadow:
    inset 0 0 6px 2px rgb(255 255 255 / 24%),
    0 0 0 1px var(--button-fill),
    0 3px 6px rgb(0 0 0 / 20%);
  cursor: pointer;
  transition: filter 150ms;
}

.button::before {
  position: absolute;
  inset: 0;
  border: 1px solid transparent;
  border-radius: inherit;
  background: linear-gradient(180deg, rgb(255 255 255 / 40%), rgb(255 255 255 / 0%)) border-box;
  mask: linear-gradient(#fff 0 0) padding-box, linear-gradient(#fff 0 0);
  mask-composite: exclude;
  content: "";
  pointer-events: none;
}

.button.button svg {
  width: 20px;
  height: 20px;
}

.button:hover {
  filter: brightness(1.06);
}

.button:focus-visible {
  outline: 3px solid var(--button-fill);
  outline-offset: 5px;
}

:global(.dark) .button.graphite {
  box-shadow:
    inset 0 0 6px 2px rgb(255 255 255 / 8%),
    0 0 0 1px var(--button-fill),
    0 3px 6px rgb(0 0 0 / 20%);
}

:global(.dark) .graphite::before {
  opacity: 0.3;
}

@media (max-width: 400px) {
  .button.button {
    gap: 10px;
    padding-inline: 20px;
    font-size: 16px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .button.button {
    transition: none;
  }
}
